window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-836f8a446881708e"]={"versions": [{"id": "FIG-836f8a446881708e", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Use-Case-Diagramm (Anwendungsfalldiagramm) im Kontext der AUTOSAR-Netzwerk-Timing-Analyse (AUTOSAR_TR_TimingAnalysis). Es definiert die Systemgrenze des Netzwerks (<code>Network</code>) und stellt die primären Anwendungsfälle für Timing-Ingenieure und Netzwerk-Architekten zur Erfüllung von Kommunikations- und Latenzanforderungen dar. Ein Notizkommentar fasst zusammen: „This diagram contains all relevant network uses-cases“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Systemgrenze: Rechteck <code>Network</code>.</li>\n<li>Akteure (Strichmännchen):</li>\n<li><code>:Timing Engineer</code> (links angeordnet)</li>\n<li><code>:Network Architekt</code> (rechts angeordnet)</li>\n<li>Anwendungsfälle (Use-Cases, ovale Elemente mit Stereotyp «network»):</li>\n<li><code>Integration of new communication</code></li>\n<li><code>Design an configuration of a new network</code></li>\n<li><code>Remapping of an existing communication link</code></li>\n<li>Beziehungen:</li>\n<li>Ungerichtete Assoziationslinien verbinden <code>:Timing Engineer</code> mit allen drei Use-Cases.</li>\n<li>Ungerichtete Assoziationslinien verbinden <code>:Network Architekt</code> mit allen drei Use-Cases.</li>\n<li>Kommentar / Annotation:</li>\n<li>Notizfeld oben links mit Text <code>This diagram contains all relevant network uses-cases</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Anwendungsfalldiagramm ohne explizite zeitliche Sequenzabfolgen oder Kontrollflüsse. Die Interaktionen modellieren funktionale Verantwortlichkeiten und Arbeitsabläufe bei der Netzwerkauslegung:</p>\n<ol class=\"fig-list\">\n<li><code>Integration of new communication</code>: Einbindung zusätzlicher Signale, PDUs oder Frames in bestehende Netzwerkstrukturen unter Berücksichtigung von Timing-Vorgaben.</li>\n<li><code>Design an configuration of a new network</code>: Initiale Auslegung und Konfiguration eines neuen Kommunikationsnetzwerks (z. B. CAN, LIN, FlexRay, Ethernet) durch Netzwerk-Architekt und Timing-Ingenieur.</li>\n<li><code>Remapping of an existing communication link</code>: Neuzuordnung oder Verlagerung bestehender Kommunikationsbeziehungen auf alternative Busse oder Gateways.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung dient als konzeptioneller Leitfaden im AUTOSAR-Timing-Analyse-Report. Für Entwickler und Systemarchitekten spezifiziert das Schaubild die Rollenteilung und Aufgabenpakete für Netzwerk-Timing-Analysen. Werkzeuge und Entwicklungsprozesse müssen die definierten Anwendungsfälle unterstützen, insbesondere den Datenaustausch bezüglich Frame-Packaging, Signal-Mapping, Bus-Scheduling und Latenzanalysen zwischen Netzwerk-Architektur und Timing-Verifikation.</p>"}, {"id": "FIG-4cdfc90fb201353c", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Use-Case-Diagramm (Anwendungsfalldiagramm) im Kontext der AUTOSAR-Netzwerk-Timing-Analyse (AUTOSAR_TR_TimingAnalysis). Es definiert die Systemgrenze des Netzwerks (<code>Network</code>) und stellt die primären Anwendungsfälle für Timing-Ingenieure und Netzwerk-Architekten zur Erfüllung von Kommunikations- und Latenzanforderungen dar. Ein Notizkommentar fasst zusammen: „This diagram contains all relevant network uses-cases“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Systemgrenze: Rechteck <code>Network</code>.</li>\n<li>Akteure (Strichmännchen):</li>\n<li><code>:Timing Engineer</code> (links angeordnet)</li>\n<li><code>:NW Data Engineer</code> (rechts oben angeordnet)</li>\n<li><code>:E/E Architect</code> (rechts unten angeordnet)</li>\n<li>Anwendungsfälle (Use-Cases, ovale Elemente mit Stereotyp «network»):</li>\n<li><code>Integration of new communication</code></li>\n<li><code>Design a configuration of a new network</code></li>\n<li><code>Remapping of an existing communication link</code></li>\n<li>Beziehungen:</li>\n<li><code>:Timing Engineer</code> ist über ungerichtete Assoziationslinien mit allen drei Use-Cases verbunden (<code>Integration of new communication</code>, <code>Design a configuration of a new network</code>, <code>Remapping of an existing communication link</code>).</li>\n<li><code>:NW Data Engineer</code> ist über ungerichtete Assoziationslinien mit allen drei Use-Cases verbunden (<code>Integration of new communication</code>, <code>Design a configuration of a new network</code>, <code>Remapping of an existing communication link</code>).</li>\n<li><code>:E/E Architect</code> ist über eine ungerichtete Assoziationslinie ausschließlich mit <code>Design a configuration of a new network</code> verbunden. Die Linie kreuzt die Verbindungslinie zwischen <code>Remapping of an existing communication link</code> und <code>:NW Data Engineer</code> mit einer Brücke (Sprungbogen).</li>\n<li>Kommentar / Annotation:</li>\n<li>Notizfeld oben links mit Text <code>This diagram contains all relevant network uses-cases</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Anwendungsfalldiagramm ohne explizite zeitliche Sequenzabfolgen oder Kontrollflüsse. Die Interaktionen modellieren funktionale Verantwortlichkeiten und Arbeitsabläufe bei der Netzwerkauslegung mit differenzierter Rollenaufteilung:</p>\n<ol class=\"fig-list\">\n<li><code>Integration of new communication</code>: Einbindung zusätzlicher Signale, PDUs oder Frames in bestehende Netzwerkstrukturen in Zusammenarbeit zwischen <code>:Timing Engineer</code> und <code>:NW Data Engineer</code>.</li>\n<li><code>Design a configuration of a new network</code>: Initiale Auslegung und Konfiguration eines neuen Kommunikationsnetzwerks, an der <code>:Timing Engineer</code>, <code>:NW Data Engineer</code> und übergeordnet der <code>:E/E Architect</code> beteiligt sind.</li>\n<li><code>Remapping of an existing communication link</code>: Neuzuordnung oder Verlagerung bestehender Kommunikationsbeziehungen, ausgeführt von <code>:Timing Engineer</code> und <code>:NW Data Engineer</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung dient als konzeptioneller Leitfaden im AUTOSAR-Timing-Analyse-Report. Für Entwickler und Integratoren spezifiziert das Diagramm eine geschärfte funktionale Rollentrennung: Der <code>:E/E Architect</code> ist nur noch an der initialen Netzwerkarchitektur und -konfiguration beteiligt, während Detailaufgaben wie Signalintegration und Umkonfigurierung bestehender Kommunikationsbeziehungen in den Verantwortungsbereich des <code>:NW Data Engineer</code> und <code>:Timing Engineer</code> fallen. Toolketten und Entwicklungsprozesse müssen diese Rollenteilung bei Berechtigungen, Modellartefakten und Übergabepunkten abbilden.</p>"}, {"id": "FIG-49e13afbba04a82f", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Use-Case-Diagramm (Anwendungsfalldiagramm) im Kontext der AUTOSAR-Netzwerk-Timing-Analyse (AUTOSAR_TR_TimingAnalysis). Es definiert die Systemgrenze des Netzwerks (<code>Network</code>) und stellt die primären Anwendungsfälle für Timing-Ingenieure und Netzwerk-Architekten zur Erfüllung von Kommunikations- und Latenzanforderungen dar. Ein Notizkommentar fasst zusammen: „This diagram contains all relevant network uses-cases“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Systemgrenze: Rechteck <code>Network</code>.</li>\n<li>Akteure (Strichmännchen):</li>\n<li><code>:Timing Engineer</code> (links angeordnet)</li>\n<li><code>:NW Data Engineer</code> (rechts oben angeordnet)</li>\n<li><code>:E/E Architect</code> (rechts unten angeordnet)</li>\n<li>Anwendungsfälle (Use-Cases, ovale Elemente mit Stereotyp «network»):</li>\n<li><code>Integration of new communication</code></li>\n<li><code>Design a configuration of a new network</code></li>\n<li><code>Remapping of an existing communication link</code></li>\n<li>Beziehungen:</li>\n<li><code>:Timing Engineer</code> ist über ungerichtete Assoziationslinien mit allen drei Use-Cases verbunden (<code>Integration of new communication</code>, <code>Design a configuration of a new network</code>, <code>Remapping of an existing communication link</code>).</li>\n<li><code>:NW Data Engineer</code> ist über ungerichtete Assoziationslinien mit allen drei Use-Cases verbunden (<code>Integration of new communication</code>, <code>Design a configuration of a new network</code>, <code>Remapping of an existing communication link</code>).</li>\n<li><code>:E/E Architect</code> ist über eine ungerichtete Assoziationslinie ausschließlich mit <code>Design a configuration of a new network</code> verbunden. Die Linie kreuzt die Verbindungslinie zwischen <code>Remapping of an existing communication link</code> und <code>:NW Data Engineer</code> mit einer Brücke (Sprungbogen).</li>\n<li>Kommentar / Annotation:</li>\n<li>Notizfeld oben links mit Text <code>This diagram contains all relevant network uses-cases</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Anwendungsfalldiagramm ohne explizite zeitliche Sequenzabfolgen oder Kontrollflüsse. Die Interaktionen modellieren funktionale Verantwortlichkeiten und Arbeitsabläufe bei der Netzwerkauslegung mit differenzierter Rollenaufteilung:</p>\n<ol class=\"fig-list\">\n<li><code>Integration of new communication</code>: Einbindung zusätzlicher Signale, PDUs oder Frames in bestehende Netzwerkstrukturen in Zusammenarbeit zwischen <code>:Timing Engineer</code> und <code>:NW Data Engineer</code>.</li>\n<li><code>Design a configuration of a new network</code>: Initiale Auslegung und Konfiguration eines neuen Kommunikationsnetzwerks, an der <code>:Timing Engineer</code>, <code>:NW Data Engineer</code> und übergeordnet der <code>:E/E Architect</code> beteiligt sind.</li>\n<li><code>Remapping of an existing communication link</code>: Neuzuordnung oder Verlagerung bestehender Kommunikationsbeziehungen, ausgeführt von <code>:Timing Engineer</code> und <code>:NW Data Engineer</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung dient als konzeptioneller Leitfaden im AUTOSAR-Timing-Analyse-Report. Für Entwickler und Integratoren spezifiziert das Diagramm eine geschärfte funktionale Rollentrennung: Der <code>:E/E Architect</code> ist nur noch an der initialen Netzwerkarchitektur und -konfiguration beteiligt, während Detailaufgaben wie Signalintegration und Umkonfigurierung bestehender Kommunikationsbeziehungen in den Verantwortungsbereich des <code>:NW Data Engineer</code> und <code>:Timing Engineer</code> fallen. Toolketten und Entwicklungsprozesse müssen diese Rollenteilung bei Berechtigungen, Modellartefakten und Übergabepunkten abbilden.</p>"}], "trans": [{"from": "FIG-836f8a446881708e", "to": "FIG-4cdfc90fb201353c", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Akteur <code>:Network Architekt</code> ersetzt durch zwei separate Akteure <code>:NW Data Engineer</code> und <code>:E/E Architect</code>.</li>\n<li>Zuordnung der Use-Cases angepasst: <code>:NW Data Engineer</code> ist mit <code>Integration of new communication</code>, <code>Design a configuration of a new network</code> und <code>Remapping of an existing communication link</code> assoziiert; <code>:E/E Architect</code> ist ausschließlich mit <code>Design a configuration of a new network</code> assoziiert.</li>\n<li>Use-Case-Beschriftung redaktionell korrigiert: <code>Design an configuration of a new network</code> geändert zu <code>Design a configuration of a new network</code>.</li>\n<li>Leitungsführung angepasst: Verbindungslinie zwischen <code>Design a configuration of a new network</code> und <code>:E/E Architect</code> kreuzt die Verbindungslinie von <code>Remapping of an existing communication link</code> zu <code>:NW Data Engineer</code> mit einer Brücke (Sprungbogen).</li>\n</ul>"}, {"from": "FIG-4cdfc90fb201353c", "to": "FIG-49e13afbba04a82f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
